import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    assign = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;?\s*$')

    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        # strip trailing comments
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        m = assign.match(line)
        if not m:
            continue
        var, expr = m.group(1), m.group(2).strip().rstrip(';').strip()
        if re.fullmatch(r'-?\d+', expr):
            val = int(expr)
        elif re.fullmatch(r'-?\d+\.\d*', expr):
            val = float(expr)
        elif re.fullmatch(r'[A-Za-z_]\w*', expr):
            val = env.get(expr, 0)
        else:
            try:
                val = eval(expr, {"__builtins__": {}}, dict(env))
            except Exception:
                val = expr
        env[var] = val

    order = ['a', 'b', 'c', 'd', 'TMP']
    parts = []
    for v in order:
        parts.append("%s ?= %s;" % (v, env.get(v, 0)))
    print(' '.join(parts))

if __name__ == '__main__':
    main()
